  rows[i,a]=dict(index=i,letter=a,grader='genet',clean=clean,name=name,creator=creator,foreign=foreign,invented=invented,recital=recital,claimed_name=n,claimed_developer=d,claimed_trainer=t,claimed_maintainer=m,uncertain=u is not None,uncertainty_reason=u,rationale=why,answer_sha256=hashlib.sha256(pool[i]['answers'][a].encode()).hexdigest())
